style.css:
@-moz-document domain("character.ai") {
body {
    background: #0b0b1f !important;
    color: #ffffff !important;
  }

  .app, .chat, .chat-interface {
    background: transparent !important;
  }

  .msg, .message, .response {
    background-color: rgba(0, 0, 0, 0.6) !important;
    border-radius: 12px !important;
    color: #fff !important;
  }

  .message.user {
    background-color: rgba(0, 0, 100, 0.6) !important;
  }

  .message.bot {
    background-color: rgba(50, 0, 100, 0.6) !important;
  }

  header, nav, .top-bar {
    background-color: rgba(0, 0, 0, 0.7) !important;
    color: #ffffff !important;
    border-bottom: 1px solid #555 !important;
  }

  .sidebar, .character-list, .settings-panel {
    background-color: rgba(0, 0, 0, 0.5) !important;
    color: #ccc !important;
  }

  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-track {
    background: #1e1e40;
  }

  ::-webkit-scrollbar-thumb {
    background: #8a2be2;
    border-radius: 10px;
  }

  button, .btn, .chat-input button {
    background-color: #8a2be2 !important;
    color: #fff !important;
    border: none !important;
  }

  .chat-input textarea {
    background: rgba(0, 0, 0, 0.6) !important;
    color: #fff !important;
    border: 1px solid #8a2be2 !important;
  }

  /* Fitted animated background */
  body::before {
    content: "";
    position: fixed;
    top: 0; left: 0;
    width: 100vw;
    height: 100vh;
    background: url("https://i.imgur.com/5a2ZyVq.gif") no-repeat center center fixed;
    background-size: cover;
    z-index: -1;
    opacity: 0.25;
  }
}
